import json
b={e['path']:e for e in json.load(open('.testivai/baselines/home__desktop/elements.json'))}
c={e['path']:e for e in json.load(open('.testivai/temp/home__desktop/elements.json'))}
n=0
for p,e in b.items():
    f=c.get(p)
    if f and (any(e[k]!=f[k] for k in 'xywidth height'.split() if k in e) or e['styleHash']!=f['styleHash']):
        print(p[-70:],[e[k] for k in('x','y','width','height')],[f[k] for k in('x','y','width','height')],e['styleHash'],f['styleHash']); n+=1
        if n>14:break
E

